import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';
import { Amplify } from 'aws-amplify';
import { BrowserRouter } from 'react-router-dom';
import outputs from './amplify_outputs.json';

// amplify_outputs.json is generated by the sandbox into src/ (see the
// "sandbox" script in package.json, which passes --outputs-out-dir src).
// CRA forbids imports from outside src/, so it must live here. It
// replaces the old Gen 1 aws-exports.js.
Amplify.configure(outputs);

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <BrowserRouter>
    <React.StrictMode>
      <App />
    </React.StrictMode>
  </BrowserRouter>
);
